with with_windows as (select id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, sum(stock_qty) over (partition by brand order by launch_date, id rows between unbounded preceding and current row) as running_stock_qty, last_value(stock_qty) ignore nulls over (order by stock_qty, id rows between unbounded preceding and current row) as last_known_stock_qty, max(stock_qty) over (partition by category) as category_max_stock_qty, corr(cost, stock_qty) over (partition by category, supplier_id) as corr_cost_stock_qty from products) select id, product_name, brand, price, cost, stock_qty, launch_date, tags, supplier_id, case when product_name rlike '^(wireless mouse|Noise-Cancel Headphones)$' then 'GROUP_B' else 'CORE' end as product_name_zone from with_windows order by cost desc, product_name_zone
